from ...config import ENBConfig

from .base_cl_tool import BaseClToolInterface
from ute_common_converter.to_bool import to_bool


class ConfigurationResetInterface(BaseClToolInterface):
    """Keywords related to Configuration Reset."""

    def reset_configuration(self, timeout='15min', ap_id=None, flags=None, **kwargs):
        """Resets configuration data.

        :param string ap_id:                         If set, will only remove existing configuration data for AP.
        :param string flags:                         Comma-separated flags for configuration reset.

        |

        :Supported flags:
            * **removeSiteId** -                     If set, will also remove autoconnection siteid.
            * **removeSecurityCredential** -         If set, will also remove security credential.
            * **removeACNonOpBackhaulParams** -      If set, will also remove non-operator owned backhaul.
            * **waitforreset** -                     If set, will wait for BTS reset.

        |

        :return: Path(s) of collected file(s).
        :rtype: list
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout}
        params.update({'apId': ap_id}) if ap_id else None
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = flags.replace(' ', '').split(',') if flags else []
        if nolog:
            flags.append('nolog')
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout,
                                               operation='configurationreset', params=params, trs_ip=ne, flags=flags)
